```python
import re
import urllib.request
import json

# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

def task_func(API_URL):
    """
    Get the public IP address of the current host from an API.

    Parameters:
    API_URL (str): URL of the API endpoint returning the IP address

    Returns:
    str: The public IP address if successful

    Raises:
    Exception: If the API request fails, raises an exception with the error message
    """
    try:
        with urllib.request.urlopen(API_URL) as response:
            data = response.read().decode('utf-8')

            # Try to parse as JSON first (common for IP APIs)
            try:
                json_data = json.loads(data)
                # Try common JSON key patterns
                for key in ['ip', 'address', 'myip', 'public_ip', 'ip_address']:
                    if key in json_data:
                        value = str(json_data[key])
                        match = re.search(IP_REGEX, value)
                        if match:
                            return match.group()
                # If no standard key found, try to find IP in the whole JSON
                match = re.search(IP_REGEX, data)
                if match:
                    return match.group()
            except json.JSONDecodeError:
                # Not JSON, try to find IP directly in text
                match = re.search(IP_REGEX, data)
                if match:
                    return match.group()

            raise ValueError("No valid IP address found in API response")

    except urllib.error.URLError as e:
        raise Exception(f"API request failed: {e.reason}")
    except urllib.error.HTTPError as e:
        raise Exception(f"API request failed with HTTP error: {e.code} - {e.reason}")
    except Exception as e:
        raise Exception(f"API request failed: {str(e)}")
